{"success": true, "data": {"stdout": "/**
 * @name 2-hop call graph extraction from buggy function or class
 * @description Extracts all functions within 2 call-graph hops of a specified
 *              buggy function. When the target is a Python class, expands to
 *              include all class methods, instantiation callers, and subclass methods.
 * @kind problem
 * @id structfuse/call-graph-2hop
 * @problem.severity recommendation
 * @precision medium
 * @tags structfuse call-graph extraction
 */

import python

external string buggyFunctionName();
external string buggyFileName();

predicate isBuggyFunction(Function f) {
  f.getName() = buggyFunctionName() and
  f.getLocation().getFile().getRelativePath() = buggyFileName()
}

predicate isBuggyClass(Class c) {
  c.getName() = buggyFunctionName() and
  c.getLocation().getFile().getRelativePath() = buggyFileName()
}

predicate isOrigin(Function f) {
  isBuggyFunction(f)
  or
  exists(Class c | isBuggyClass(c) and f.getScope() = c)
}

predicate directCallEdge(Function caller, Function callee) {
  exists(Call call |
    call.getScope() = caller and
    (
      // Direct name call: func()
      callee.getName() = call.getFunc().(Name).getId() and
      caller.getEnclosingModule() = callee.getEnclosingModule()
      or
      // Attribute call: obj.method() — match by name within the same package
      exists(string methodName |
        methodName = call.getFunc().(Attribute).getName() and
        callee.getName() = methodName and
        caller.getLocation().getFile().getRelativePath().prefix(
          caller.getLocation().getFile().getRelativePath().indexOf("/")
        ) =
        callee.getLocation().getFile().getRelativePath().prefix(
          callee.getLocation().getFile().getRelativePath().indexOf("/")
        )
      )
    )
  ) and
  caller != callee
}

// ClassName() instantiation — caller invokes the class constructor
predicate classInstantiationCaller(Function caller) {
  exists(Class c, Call call |
    isBuggyClass(c) and
    call.getScope() = caller and
    (
      call.getFunc().(Name).getId() = c.getName() and
      caller.getEnclosingModule() = c.getEnclosingModule()
      or
      call.getFunc().(Attribute).getName() = c.getName() and
      caller.getLocation().getFile().getRelativePath().prefix(
        caller.getLocation().getFile().getRelativePath().indexOf("/")
      ) =
      c.getLocation().getFile().getRelativePath().prefix(
        c.getLocation().getFile().getRelativePath().indexOf("/")
      )
    )
  ) and
  not isOrigin(caller)
}

// Direct subclass methods (one level of inheritance, name-based resolution)
predicate isSubclassMethod(Function f) {
  exists(Class buggy, Class sub |
    isBuggyClass(buggy) and
    sub.getABase().(Name).getId() = buggy.getName() and
    sub.getLocation().getFile().getRelativePath().prefix(
      sub.getLocation().getFile().getRelativePath().indexOf("/")
    ) =
    buggy.getLocation().getFile().getRelativePath().prefix(
      buggy.getLocation().getFile().getRelativePath().indexOf("/")
    ) and
    f.getScope() = sub
  ) and
  not isOrigin(f)
}

predicate hop1(Function f, string direction) {
  (
    exists(Function origin |
      isOrigin(origin) and
      (
        directCallEdge(origin, f) and direction = "callee"
        or
        directCallEdge(f, origin) and direction = "caller"
      )
    )
    or
    classInstantiationCaller(f) and direction = "caller"
    or
    isSubclassMethod(f) and direction = "subclass"
  ) and
  not isOrigin(f)
}

predicate hop2(Function f, string direction) {
  exists(Function mid |
    hop1(mid, _) and
    (
      directCallEdge(mid, f) and direction = "callee"
      or
      directCallEdge(f, mid) and direction = "caller"
    ) and
    not isOrigin(f) and
    not hop1(f, _)
  )
}

predicate inScope(Function f, int hopDistance, string direction) {
  isOrigin(f) and hopDistance = 0 and direction = "origin"
  or
  hop1(f, direction) and hopDistance = 1
  or
  hop2(f, direction) and hopDistance = 2
}

from Function f, int hopDistance, string direction, File file, int startLine, int endLine
where
  inScope(f, hopDistance, direction) and
  file = f.getLocation().getFile() and
  startLine = f.getLocation().getStartLine() and
  endLine = f.getLocation().getEndLine()
select
  f.getName() as target_func,
  hopDistance as hop_distance,
  direction,
  file.getRelativePath() as file_path,
  startLine as start_line,
  endLine as end_line
